mapper.select:


    c.del_flag = '0'

        and c.contract_no like concat('%', #{contractNo}, '%')


        and c.dispatch_enterprise_id = #{dispatchEnterpriseId}


        and c.employer_enterprise_id = #{employerEnterpriseId}


        and c.person_id = #{personId}


        and c.person_name like concat('%', #{personName}, '%')


        and (c.person_name like concat('%', #{personKeyword}, '%') or c.id_card like concat('%', #{personKeyword}, '%'))


        and (de.enterprise_name like concat('%', #{enterpriseKeyword}, '%') or ee.enterprise_name like concat('%', #{enterpriseKeyword}, '%'))


        and c.contract_type = #{contractType}


        and c.contract_status = #{contractStatus}


        and c.ocr_status = #{ocrStatus}


        and c.clause_check_status = #{clauseCheckStatus}


        and c.blockchain_hash is not null and c.blockchain_hash != ''


        and (c.blockchain_hash is null or c.blockchain_hash = '')


        and (c.contract_status in ('0', '1') or c.filing_no is null or c.filing_no = '' or c.filing_time is null)


        and c.contract_status = '2' and c.filing_no is not null and c.filing_no != '' and c.filing_time is not null


        and c.sign_date >= #{signDateBegin}


        and c.sign_date <= #{signDateEnd}


        and c.end_date >= #{endDateBegin}


        and c.end_date <= #{endDateEnd}


        and c.region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}
    ${params.enterpriseDataScope}

order by c.create_time desc, c.contract_id desc

select base.*,
       timestampdiff(day, curdate(), base.end_date) as days_to_expire,
       case
           when base.end_date < curdate() then 'expired'
           when timestampdiff(day, curdate(), base.end_date) <= 7 then 'urgent'
           else 'soon'
       end as expiry_level,
       log.last_remind_time,
       case when log.last_remind_time is null then 'none' else 'reminded' end as remind_status
from (


        c.del_flag = '0'
        and c.end_date is not null
        and c.contract_status not in ('4', '5')

            and c.end_date >= #{endDateBegin}


            and c.end_date <= #{endDateEnd}


            and c.end_date between curdate() and date_add(curdate(), interval 30 day)


            and c.contract_no like concat('%', #{contractNo}, '%')


            and c.dispatch_enterprise_id = #{dispatchEnterpriseId}


            and c.employer_enterprise_id = #{employerEnterpriseId}


            and c.contract_type = #{contractType}


            and (c.person_name like concat('%', #{personKeyword}, '%') or c.id_card like concat('%', #{personKeyword}, '%'))


            and (de.enterprise_name like concat('%', #{enterpriseKeyword}, '%') or ee.enterprise_name like concat('%', #{enterpriseKeyword}, '%'))


            and c.region_code like concat(#{regionCode}, '%')

        ${params.regionDataScope}
        ${params.enterpriseDataScope}

) base
left join (
    select contract_id, max(action_time) as last_remind_time
    from t_contract_action_log
    where action_type = 'expiry_remind'
    group by contract_id
) log on base.contract_id = log.contract_id
order by base.end_date asc, base.contract_id desc

select base.*,
       trim(both '；' from concat(
           case when base.contract_status in ('0', '1') then '合同未完成备案；' else '' end,
           case when base.filing_no is null or base.filing_no = '' then '缺少备案编号；' else '' end,
           case when base.filing_time is null then '缺少备案时间；' else '' end
       )) as risk_reason,
       w.warn_id as warning_id,
       w.warn_status as warning_status
from (


        c.del_flag = '0'
        and (c.contract_status in ('0', '1') or c.filing_no is null or c.filing_no = '' or c.filing_time is null)

            and c.contract_no like concat('%', #{contractNo}, '%')


            and c.dispatch_enterprise_id = #{dispatchEnterpriseId}


            and c.employer_enterprise_id = #{employerEnterpriseId}


            and c.contract_type = #{contractType}


            and c.contract_status = #{contractStatus}


            and (c.person_name like concat('%', #{personKeyword}, '%') or c.id_card like concat('%', #{personKeyword}, '%'))


            and (de.enterprise_name like concat('%', #{enterpriseKeyword}, '%') or ee.enterprise_name like concat('%', #{enterpriseKeyword}, '%'))


            and c.region_code like concat(#{regionCode}, '%')

        ${params.regionDataScope}
        ${params.enterpriseDataScope}

) base
left join t_warning w on w.source_module = 'CONTRACT'
    and w.warn_type = 'UNFILED_CONTRACT'
    and w.target_object_id = base.contract_id
    and w.warn_status in ('0', '1', '4')
order by base.create_time desc, base.contract_id desc
